# -*- coding: utf-8 -*-
from ._helpers import intro, schema, fall, mc

KURS = dict(
    id="u03", gebiet="upc", titel="Die Verletzungsklage: vom Schriftsatz zur Entscheidung",
    untertitel="Klageschrift, Zustellung, Fristen, Klageerwiderung und Widerklage, Verfahrenssprache, Berichterstatter, Zwischenverfahren, mündliche Verhandlung – und was unterwegs passieren kann",
    farbe="#5e3f9e", icon="verletzung",
    beschreibung="Der Gang des Verletzungsverfahrens nach der Verfahrensordnung: Klageschrift und Anlagen (Sanofi/Amgen), CMS-Workflows (Edwards/Meril, Avago/Tesla), Zustellung in Drittstaaten (NEC/TCL), Fristen (bioMérieux/Labrador), Verfahrenssprache (TP-Link/Huawei, 10x/Curio), Berichterstatter und R. 333 (Huawei/MediaTek, Vivo/Sun Patent), mündliche Verhandlung, Klageänderung (VMR/NJOY), Rücknahme (Juul/NJOY), Streithilfe (Strabag/Swarco), Versäumnis (Suinno/Microsoft) und rechtliches Gehör (Siemens/Hologic, DexCom/Abbott).",
    kapitel=[
        dict(id="u03a", titel="Klageschrift, Zustellung, Fristen", einheiten=[
            schema("u03a-0", "Prüfungsschema: Verletzungsklage vor dem EPG", "upc_schema_verletzungsklage",
                   "Zulässigkeit (Zuständigkeit, Parteien, Vertretung, Klageschrift, Sprache), Begründetheit (Auslegung, Benutzungshandlung, Einwendungen, Rechtsbestand) und Rechtsfolgen – das Schema ordnet die Prüfungspunkte, dieser Kurs verfolgt den Weg des Verfahrens vom Schriftsatz bis zur Entscheidung."),
            fall("u03a-1", "Die vergessenen Anlagen",
                 "Die S-SA reicht bei der Lokalkammer München eine Verletzungsklage gegen die A-Inc. ein. Die Klageschrift nimmt auf 40 Anlagen Bezug – Patentschrift, Merkmalsgliederung, Testberichte –, die S-SA lädt sie aber erst drei Wochen nach der Zustellung der Klageschrift ins CMS hoch. Die A-Inc. meint, die Zustellung sei unwirksam, weil die Anlagen fehlten; Einspruchs- und Erwiderungsfrist hätten deshalb nicht zu laufen begonnen. S-SA hält dagegen: Die Fristen seien fest, R. 9.3 VerfO erlaube eine Verlängerung nur ausnahmsweise.",
                 "Ist die Zustellung der Klageschrift ohne die Anlagen unwirksam?", False,
                 ["**Nein!** Die Klageschrift muss die Angaben nach R. 13.1 VerfO enthalten; Anlagen sind **gleichzeitig** einzureichen (R. 13.2 VerfO). Die Zustellung nach R. 271 VerfO ist aber auch ohne die in Bezug genommenen Anlagen wirksam, wenn der Beklagte seine Rechte auch ohne sie wahrnehmen kann – und das kann er, weil die Klageschrift selbst die Anträge, den Verletzungsvorwurf und die Merkmalsanalyse (R. 13.1 lit. k bis n) enthält (Sanofi/Amgen).",
                  "Der Verstoß gegen R. 13.2 bleibt aber nicht folgenlos: Die Fristen für den Einspruch (ein Monat, R. 19.1) und die Klageerwiderung (drei Monate, R. 23) sind um den Zeitraum zu **verlängern**, in dem die Anlagen nicht verfügbar waren; auf Art und Inhalt der Anlagen kommt es nicht an (Sanofi/Amgen). Das ist eine Frage der Fairness (Präambel Nr. 5), nicht der Fristverlängerung nach R. 9.3 lit. a VerfO, die das Berufungsgericht nur mit Zurückhaltung und unter außergewöhnlichen Umständen gewährt – die bloße Angleichung paralleler Fristen etwa genügt nicht (bioMérieux/Labrador). Fristen werden nach R. 300 VerfO berechnet; Gerichtsferien hemmen sie nicht."],
                 merke="Ohne Anlagen ist die Zustellung wirksam, aber die Fristen des Beklagten verlängern sich um die Zeit ohne Anlagen; R. 9.3 bleibt die enge Ausnahme.",
                 level=2, concepts=["upc_klageschrift", "upc_zustellung", "upc_fristen"],
                 norms=["R. 13.2 VerfO", "R. 271 VerfO", "R. 23 VerfO", "R. 9.3 VerfO"],
                 cases=["upc_coa_sanofi_amgen_zustellung", "upc_coa_biomerieux_labrador_fristen"], step="step:upc_schema_verletzungsklage.1.4"),
            fall("u03a-2", "E-Mail nach Shenzhen",
                 "Die N-Corp. verklagt vor einer Lokalkammer die T-Ltd. mit Sitz in Shenzhen. Um das langwierige Verfahren nach dem Haager Zustellungsübereinkommen zu vermeiden, beantragt sie, die Klageschrift per E-Mail an den europäischen Vertriebsleiter der T-Ltd. zuzustellen, der die Gespräche vor der Klage geführt hat; hilfsweise beantragt sie die öffentliche Zustellung durch Aushang bei der Lokalkammer nach R. 275 VerfO. Einen Zustellversuch nach dem HZÜ hat sie nicht unternommen.",
                 "Kann das Gericht die beantragte Zustellung zulassen?", False,
                 ["**Nein!** Außerhalb der Vertragsmitgliedstaaten stellt die Kanzlei die Klageschrift nach R. 274.1 lit. a VerfO zu: nach der EU-Zustellungsverordnung, soweit anwendbar, nach dem **Haager Zustellungsübereinkommen** oder auf diplomatischem Weg. Erst wenn eine solche Zustellung nicht bewirkt werden konnte, kommen andere Verfahren nach dem Recht des Zustellungsstaats oder eine vom Gericht nach R. 275 zugelassene Ersatzzustellung in Betracht (R. 274.1 lit. b). Vor einer Ersatzzustellung sind deshalb normalerweise **Zustellversuche nach dem HZÜ** zu unternehmen (NEC/TCL).",
                  "Eine E-Mail an eine nicht empfangsberechtigte Person – der Vertriebsleiter ist kein Vertreter nach R. 8.1 und keine Zustelladresse nach R. 271.1 – ist keine wirksame Zustellung; auch die öffentliche Zustellung durch Aushang scheidet in diesem Stadium aus (NEC/TCL). Die Zustellung darf zudem nicht auf eine Weise erfolgen, die mit dem Recht des Zustellungsstaats unvereinbar ist (R. 274.2, R. 275.4 VerfO). Die N-Corp. muss den Weg über das HZÜ gehen; die Kanzlei teilt ihr das Zustelldatum mit (R. 274.3)."],
                 merke="Erst HZÜ, dann Ersatzzustellung: R. 275 ist die Reserve für gescheiterte Zustellungen, nicht die Abkürzung für ungeduldige Kläger.",
                 level=2, concepts=["upc_zustellung"],
                 norms=["R. 274 VerfO", "R. 275 VerfO", "R. 271 VerfO"],
                 cases=["upc_coa_nec_tcl_zustellung_china"], step="step:upc_schema_verletzungsklage.1.4"),
            mc("u03a-3", "Der falsche Workflow",
               "Die Beklagte reicht ihre Klageerwiderung am letzten Tag der Dreimonatsfrist elektronisch ein, verwendet dabei aber nicht den dafür vorgesehenen CMS-Workflow „Statement of defence“, sondern lädt den Schriftsatz als „sonstiges Dokument“ hoch. Der Kläger beantragt eine Versäumnisentscheidung. Wie ist die Rechtslage?",
               ["Die Klageerwiderung ist nicht wirksam eingereicht; die Frist ist versäumt, und die Versäumnisentscheidung ergeht nach R. 355 VerfO",
                "Die Parteien müssen nach R. 4.1 VerfO die amtlichen Online-Formulare einschließlich der CMS-Workflows verwenden; die Nutzung des falschen Workflows steht der Fristwahrung aber nicht entgegen, und in der Anfangsphase des EPG gilt ein großzügiger Maßstab",
                "Die Einreichung ist unwirksam, wird aber rückwirkend wirksam, wenn die Beklagte den Schriftsatz binnen 14 Tagen über den richtigen Workflow nachreicht",
                "R. 4 VerfO gilt nur für die Klageschrift; für die Klageerwiderung gibt es keine Formvorschriften"], 1,
               ["Schriftsätze sind zu unterzeichnen und **elektronisch** bei der Kanzlei einzureichen; die Parteien sind gehalten, die amtlichen Online-Formulare zu verwenden (R. 4.1 VerfO, Art. 44 EPGÜ). Die Lokalkammer München hat daraus abgeleitet, dass auch die gesonderten **CMS-Workflows** zu nutzen sind (Edwards/Meril). Wird der falsche Workflow gewählt, ist der Schriftsatz aber gleichwohl fristgerecht eingegangen – der Eingang wird durch die elektronische Quittung mit Datum und Ortszeit bestätigt (R. 4.1 Satz 3); die unterbliebene Nutzung des Workflows steht der **Fristwahrung nicht entgegen**, zumal in der Anfangsphase des Gerichts ein großzügiger Maßstab angezeigt ist (LK Hamburg, Avago/Tesla).",
                "Eine Versäumnisentscheidung nach R. 355.1 lit. a VerfO setzt voraus, dass eine Handlung innerhalb der Frist versäumt wurde; das ist hier nicht der Fall. Fällt das CMS aus, darf ausnahmsweise in Papierform eingereicht werden, die elektronische Kopie ist nachzureichen (R. 4.2 VerfO). Klausurhinweis: Die Klageerwiderung muss die Angaben nach R. 24 VerfO enthalten und – wenn der Rechtsbestand bestritten wird – die Widerklage auf Nichtigerklärung nach R. 25 VerfO."],
               merke="Der Workflow ist Pflicht, aber kein Fristfallstrick: Wer rechtzeitig hochlädt, hat die Frist gewahrt.",
               level=1, concepts=["upc_klageschrift", "upc_fristen", "upc_versaeumnisentscheidung"],
               norms=["R. 4 VerfO", "R. 23 VerfO", "R. 24 VerfO", "R. 355 VerfO"],
               cases=["upc_cfi_edwards_meril_cms", "upc_cfi_avago_tesla_teilnichtigkeit"], step="step:upc_schema_verletzungsklage.1.4"),
        ]),
        dict(id="u03b", titel="Sprache, Berichterstatter, Zwischenverfahren, mündliche Verhandlung", einheiten=[
            intro("u03b-0", "Wer das Verfahren leitet und in welcher Sprache",
                  "Das Verfahren hat **drei Abschnitte** (Art. 52 EPGÜ, R. 10 VerfO). Im **schriftlichen Verfahren** folgen auf die Klageschrift die Klageerwiderung (drei Monate, R. 23, Inhalt R. 24) mit etwaiger Widerklage auf Nichtigerklärung (R. 25), die Erwiderung des Klägers auf die Widerklage samt Replik und Änderungsantrag nach R. 30 (zwei Monate, R. 29), dann Replik und Duplik (R. 29, 29A). Die **Verfahrenssprache** wählt der Kläger in der Klageschrift aus den Sprachen der Kammer (Art. 49 Abs. 1, 2 EPGÜ, R. 14 VerfO); die deutschen Lokalkammern lassen Englisch zu. Die Parteien können die Patentsprache vereinbaren (Abs. 3), der Spruchkörper kann sie mit Zustimmung der Parteien wählen (Abs. 4), und der Präsident des Gerichts erster Instanz kann sie auf Antrag einer Partei aus Fairnessgründen anordnen (Abs. 5, R. 323 VerfO; TP-Link/Huawei). Vor der Zentralkammer gilt die Patentsprache (Abs. 6), vor dem Berufungsgericht die Sprache der ersten Instanz (Art. 50 EPGÜ). Verdolmetschung gibt es nur, soweit angemessen (Art. 51 Abs. 2 EPGÜ, R. 109 VerfO; 10x/Curio). Der Vorsitzende bestimmt einen rechtlich qualifizierten Richter zum **Berichterstatter** (R. 18), der das schriftliche Verfahren und das **Zwischenverfahren** leitet (R. 331, 334): Zwischenanhörung per Videokonferenz, Fragen, Beweisanordnungen, Streitwert, Vergleichsgespräch (R. 101 bis 106), Abschluss binnen drei Monaten (R. 101.3). Seine Anordnungen überprüft der Spruchkörper auf Antrag binnen 15 Tagen (**R. 333**); er kann jede Frage an den Spruchkörper verweisen (R. 102; Vivo/Sun Patent). Die **mündliche Verhandlung** vor dem Spruchkörper leitet der Vorsitzende (R. 111, 112); sie ist öffentlich und wird aufgezeichnet (Art. 45 EPGÜ, R. 115), soll einen Tag nicht überschreiten (R. 113) und wird mindestens zwei Monate vorher anberaumt (R. 108). Wer fernbleibt, wird auf seine Schriftsätze verwiesen (R. 116.3); die Entscheidung ergeht schriftlich, in der Regel binnen sechs Wochen (R. 118.6).",
                  concepts=["upc_verfahrensablauf", "upc_verfahrenssprache", "upc_berichterstatter"],
                  norms=["Art. 49 EPGÜ", "R. 14 VerfO", "R. 101 VerfO", "R. 113 VerfO"],
                  cases=["upc_cfi_tplink_huawei_sprache", "upc_cfi_huawei_mediatek_r333"]),
            fall("u03b-1", "Englisch für alle Beklagten",
                 "Die H-Technologies erhebt vor der Lokalkammer München auf Deutsch Verletzungsklage aus einem in englischer Sprache erteilten Patent gegen fünf Gesellschaften der T-Gruppe mit Sitz in China, Hongkong, den Niederlanden, Polen und Deutschland. Die Beklagten beantragen mit der Klageerwiderung nach R. 323 VerfO, die Verfahrenssprache in die Patentsprache Englisch zu ändern: Ihre interne Arbeitssprache sei Englisch, und die Verteidigung müsse zwischen fünf Gesellschaften in drei Ländern koordiniert werden. H-Technologies hält dagegen, sie habe als Klägerin das Wahlrecht, und die deutsche Tochter der T-Gruppe verstehe Deutsch.",
                 "Kann die Verfahrenssprache gegen den Willen der Klägerin in die Patentsprache geändert werden?", True,
                 ["**Ja!** Das Wahlrecht des Klägers nach R. 14 VerfO ist nicht das letzte Wort. Auf Ersuchen einer Partei kann der Präsident des Gerichts erster Instanz nach Anhörung der anderen Parteien und des Spruchkörpers **aus Gründen der Fairness** anordnen, dass die Sprache, in der das Patent erteilt wurde, Verfahrenssprache wird (Art. 49 Abs. 5 EPGÜ). Der Antrag ist der Klageerwiderung beizufügen; der Berichterstatter leitet ihn dem Präsidenten zu, die Gegenseite hat zehn Tage zur Stellungnahme (R. 323 VerfO). Dabei sind **alle erheblichen Umstände** abzuwägen, insbesondere der Standpunkt des Beklagten.",
                  "Angesichts der strengen Fristen der Verfahrensordnung sind die **interne Arbeitssprache** der Parteien und der **Koordinierungsbedarf** mehrerer Beklagter wichtige Faktoren (LK München, TP-Link/Huawei); das Berufungsgericht stellt auf die Waffengleichheit ab, insbesondere die Sprache des Beklagten. Der Präsident kann die Anordnung mit Übersetzungs- und Dolmetschvorkehrungen verbinden (R. 323.3). Anders die Verdolmetschung in der mündlichen Verhandlung: Sie wird nur gewährt, soweit angemessen, um einer Partei die aktive Teilnahme zu ermöglichen; Vertreter, die die Verfahrenssprache beherrschen, dürfen nicht in einer anderen Sprache verhandeln (LK Düsseldorf, 10x/Curio)."],
                 merke="Der Kläger wählt die Sprache, aber Fairness kann sie auf die Patentsprache umstellen; Verdolmetschung ist Hilfe für die Partei, kein Komfort für den Anwalt.",
                 level=2, concepts=["upc_verfahrenssprache"],
                 norms=["Art. 49 Abs. 5 EPGÜ", "R. 14 VerfO", "R. 323 VerfO", "R. 109 VerfO"],
                 cases=["upc_cfi_tplink_huawei_sprache", "upc_cfi_10x_curio_verdolmetschung"], step="step:upc_schema_verletzungsklage.1.5"),
            mc("u03b-2", "Der Berichterstatter und R. 333",
               "Der Berichterstatter lehnt in einem Verletzungsverfahren den Antrag der Beklagten ab, die Frist für die Duplik zu verlängern. Welche Aussage über die Anfechtung dieser Anordnung ist richtig?",
               ["Die Beklagte kann unmittelbar Berufung zum Berufungsgericht einlegen, weil jede Anordnung des Berichterstatters nach R. 220.1 VerfO berufungsfähig ist",
                "Die Beklagte kann binnen 15 Tagen die Überprüfung durch den Spruchkörper beantragen (R. 333 VerfO); dessen Entscheidung ist eine prozessuale Entscheidung, gegen die Berufung nur mit Zulassung nach R. 220.2 VerfO oder im Wege der Ermessensüberprüfung möglich ist",
                "Die Anordnung ist unanfechtbar, weil die Verfahrensleitung allein dem Berichterstatter obliegt",
                "Die Beklagte muss den Vorsitzenden Richter anrufen, der den Berichterstatter überstimmen kann"], 1,
               ["Während des schriftlichen Verfahrens und des Zwischenverfahrens obliegt die Verfahrensleitung dem **Berichterstatter** (R. 331.1 VerfO); er kann Fristen verlängern oder verkürzen, die Reihenfolge der Streitpunkte festlegen und Anordnungen nach R. 103 bis 109 treffen (R. 334). Verfahrensleitende Anordnungen des Berichterstatters oder des Vorsitzenden werden auf begründeten Antrag einer Partei vom **Spruchkörper überprüft**; der Antrag ist binnen **15 Tagen** ab Zustellung zu stellen, gebührenpflichtig, und die Gegenseite erhält rechtliches Gehör (R. 333.1 bis 333.3 VerfO). Die Entscheidung des Spruchkörpers ist eine prozessuale Entscheidung im Sinne von R. 220.2 (R. 333.5), also nur mit Zulassung oder über die Ermessensüberprüfung nach R. 220.3 angreifbar.",
                "Grenze: Ein Antrag nach R. 333.1 ist unstatthaft, wenn der Spruchkörper für das betreffende Verfahren gar nicht zuständig ist – etwa bei der Entscheidung des Berichterstatters über die Akteneinsicht Dritter nach R. 262.1 lit. b (LK München, Huawei/MediaTek). Umgekehrt kann der Berichterstatter jede Frage von sich aus dem Spruchkörper vorlegen (R. 102.1), auch im schriftlichen Verfahren (Vivo/Sun Patent)."],
               merke="Gegen den Berichterstatter hilft der Spruchkörper (R. 333, 15 Tage), gegen den Spruchkörper nur die Zulassung oder R. 220.3 – nicht die Berufung nach R. 220.1.",
               level=2, concepts=["upc_berichterstatter", "upc_zwischenverfahren", "upc_ermessensueberpruefung"],
               norms=["R. 331 VerfO", "R. 333 VerfO", "R. 334 VerfO", "R. 220.2 VerfO"],
               cases=["upc_cfi_huawei_mediatek_r333", "upc_coa_vivo_sunpatent_einspruch_hauptverfahren"]),
            fall("u03b-3", "Sicherheit nicht geleistet",
                 "Die S-Oy unterliegt in erster Instanz und legt Berufung ein. Auf Antrag der Berufungsbeklagten M-Corp. ordnet das Berufungsgericht an, dass die S-Oy binnen sechs Wochen Prozesskostensicherheit leistet (Art. 69 Abs. 4 EPGÜ, R. 158 VerfO). Die Frist verstreicht ohne Zahlung. Die M-Corp. beantragt eine Versäumnisentscheidung. Die S-Oy wendet ein, nach R. 355.2 VerfO dürfe eine Versäumnisentscheidung nur ergehen, wenn die vorgebrachten Tatsachen den Anspruch rechtfertigten – das habe das Gericht nicht geprüft.",
                 "Kann gegen die S-Oy eine Versäumnisentscheidung ergehen, ohne dass das Gericht nach R. 355.2 VerfO prüft, ob die Tatsachen den Anspruch rechtfertigen?", True,
                 ["**Ja!** Nach R. 355.1 lit. a VerfO kann auf Antrag eine Versäumnisentscheidung ergehen, wenn die Verfahrensordnung das für die Versäumung einer Frist vorsieht; R. 158.5 VerfO sieht das für die nicht geleistete Prozesskostensicherheit ausdrücklich vor. R. 355.2 schützt nur den **Beklagten oder Widerbeklagten**: Gegen ihn darf eine Versäumnisentscheidung nur ergehen, wenn die vom Kläger vorgebrachten Tatsachen den Anspruch rechtfertigen. Im Berufungsverfahren gilt der **Berufungskläger als Kläger**; R. 355.2 ist deshalb nicht anwendbar, wenn der Berufungsbeklagte die Versäumnisentscheidung gegen den Berufungskläger beantragt, weil dieser eine Frist versäumt oder die Sicherheit nicht geleistet hat (Suinno/Microsoft).",
                  "Dasselbe gilt, wenn der Berufungskläger nicht zur mündlichen Verhandlung erscheint (R. 355.1 lit. b). Die Versäumnisentscheidung ist vollstreckbar (R. 355.4); die S-Oy kann binnen eines Monats Einspruch gegen sie erheben, muss die Säumnis erklären, die Gebühr zahlen und die versäumte Handlung nachholen (R. 356 VerfO). Nicht zu verwechseln mit R. 116 VerfO: Wer der mündlichen Verhandlung fernbleibt, wird so behandelt, als beriefe er sich nur auf seine Schriftsätze; das Gericht muss nicht vertagen (R. 116.2, 116.3), kann aber nach R. 355 vorgehen (R. 116.5)."],
                 merke="R. 355.2 schützt den Beklagten, nicht den Berufungskläger: Wer die angeordnete Sicherheit nicht leistet, verliert durch Versäumnisentscheidung.",
                 level=3, concepts=["upc_versaeumnisentscheidung", "upc_prozesskostensicherheit", "upc_muendliche_verhandlung"],
                 norms=["R. 355 VerfO", "R. 356 VerfO", "R. 158.5 VerfO", "R. 116 VerfO"],
                 cases=["upc_coa_suinno_microsoft_versaeumnis"], step="step:upc_schema_kosten.2"),
        ]),
        dict(id="u03c", titel="Änderung, Rücknahme, Streithilfe und rechtliches Gehör", einheiten=[
            intro("u03c-0", "Was unterwegs passieren kann",
                  "Vier Weichen im laufenden Verfahren. **Klageänderung** (R. 263 VerfO): Eine Partei kann jederzeit die Zulassung einer Änderung oder Erweiterung beantragen, muss aber begründen, warum sie nicht schon im ursprünglichen Schriftsatz stand; die Zulassung wird verweigert, wenn die Änderung bei gebotener Sorgfalt früher möglich war oder die Gegenseite unangemessen behindert (R. 263.2). Die bedingungslose Beschränkung ist immer zulässig (R. 263.3). Neue Nichtigkeitsgründe oder Entgegenhaltungen gegen das erteilte Patent in der Erwiderung auf einen Änderungsantrag sind Klageänderungen (VMR/NJOY). **Rücknahme** (R. 265): bis zur Endentscheidung auf Antrag, nach Anhörung der Gegenseite und nicht gegen deren berechtigtes Interesse an einer Entscheidung; Widerklagen bleiben unberührt. Bei Rücknahme vor Abschluss des schriftlichen Verfahrens erstattet die Kanzlei **50 %** der Gebühren (R. 370.9 lit. b) – seit 1. Januar 2026, für früher eingereichte Klagen noch 60 % (Juul/NJOY). Erledigt sich die Hauptsache, weist das Gericht die Klage nach R. 360 ab und entscheidet über die Kosten danach, ob der Beklagte Anlass zur Klage gegeben hat (LK München, Dolby/Roku). **Streithilfe** (R. 313 bis 316): Wer ein rechtliches Interesse hat, kann bis zum Ende des schriftlichen Verfahrens zur Unterstützung einer Partei beitreten; der Berichterstatter entscheidet, der Streithelfer wird als Partei behandelt und ist an die Entscheidung gebunden – aber er hängt an seiner Partei (Strabag/Swarco). **Rechtliches Gehör** (Art. 76 EPGÜ, R. 264): Das Gericht entscheidet nur über die Anträge der Parteien und nur auf Grundlage von Gründen, Tatsachen und Beweismitteln, zu denen sie Stellung nehmen konnten; die Gründe müssen den Kern des Vortrags behandeln (Siemens/Hologic).",
                  concepts=["upc_klageaenderung", "upc_ruecknahme", "upc_streithilfe"],
                  norms=["R. 263 VerfO", "R. 265 VerfO", "R. 313 VerfO", "Art. 76 EPGÜ"],
                  cases=["upc_coa_juul_njoy_gebuehren", "upc_cfi_dolby_roku_veranlassung", "upc_coa_strabag_swarco_streithilfe"]),
            fall("u03c-1", "Die nachgeschobene Entgegenhaltung",
                 "Die V-GmbH erhebt vor der Zentralkammer Nichtigkeitsklage gegen ein Patent der N-Inc. und stützt sich auf zwei Entgegenhaltungen. Die N-Inc. verteidigt das Patent in der Klageerwiderung und stellt hilfsweise einen Antrag auf Änderung des Patents (R. 50.2, R. 30 VerfO). In ihrer Erwiderung auf den Änderungsantrag (R. 43.3 VerfO) führt die V-GmbH eine dritte Entgegenhaltung ein und greift damit nicht nur die geänderten, sondern auch die erteilten Ansprüche wegen fehlender Neuheit an. Einen Antrag nach R. 263 VerfO stellt sie nicht.",
                 "Muss das Gericht die neue Entgegenhaltung gegen das Patent in erteilter Fassung berücksichtigen?", False,
                 ["**Nein!** Die Erwiderung auf den Änderungsantrag nach R. 43.3 VerfO dient der Auseinandersetzung mit den **geänderten** Ansprüchen; sie kann Ausführungen nach R. 44 lit. d bis h und hilfsweise Nichtverletzungsargumente enthalten. Sie eröffnet dem Nichtigkeitskläger aber nicht die Möglichkeit, **neue Nichtigkeitsgründe oder neue Entgegenhaltungen gegen das Patent in erteilter Fassung** einzuführen. Das ist eine Klageänderung, die der Zulassung nach R. 263 VerfO bedarf: Die V-GmbH müsste darlegen, dass die Entgegenhaltung mit gebotener Sorgfalt nicht früher auffindbar war und die N-Inc. nicht unangemessen behindert wird (R. 263.2; VMR/NJOY).",
                  "Das folgt aus dem **Front-loading**: Die Nichtigkeitsklage muss alle Gründe, Tatsachen und Beweismittel enthalten (R. 44 VerfO, für die Widerklage R. 25.1). Gegen die geänderten Ansprüche darf die dritte Entgegenhaltung dagegen verwendet werden, denn auf den Änderungsantrag reagiert der Kläger zum ersten Mal. Und Fairness bleibt das Korrektiv: Neue Beweise zum allgemeinen Fachwissen als Reaktion auf die Klageerwiderung können zulässig sein (VMR/NJOY). Ohne Zulassungsantrag bleibt die Entgegenhaltung für die erteilte Fassung außer Betracht (R. 9.2 VerfO)."],
                 merke="Der Änderungsantrag öffnet die Tür nur für die geänderten Ansprüche; neue Angriffe auf das erteilte Patent brauchen die Zulassung nach R. 263.",
                 level=3, concepts=["upc_klageaenderung", "upc_front_loaded", "upc_aenderung_patent"],
                 norms=["R. 263 VerfO", "R. 43 VerfO", "R. 44 VerfO", "R. 30 VerfO"],
                 cases=["upc_coa_vmr_njoy_aenderung"], step="step:upc_schema_nichtigkeit.3"),
            fall("u03c-2", "Der widersprechende Streithelfer",
                 "Die S-AG verliert vor einer Lokalkammer eine Verletzungsklage gegen die W-GmbH und legt Berufung ein. Ihr Zulieferer Z, der die angegriffenen Bauteile herstellt, ist dem Verfahren als Streithelfer auf Seiten der S-AG beigetreten und hat ebenfalls Berufung eingelegt. Dann schließen die S-AG und die W-GmbH einen Vergleich; die S-AG nimmt ihre Berufung zurück. Z widerspricht der Rücknahme und will die Berufung allein weiterführen, weil er an dem Vergleich nicht beteiligt ist und ein eigenes Interesse an der Feststellung der Nichtverletzung hat.",
                 "Kann Z die Berufung nach der Rücknahme durch die S-AG allein weiterführen?", False,
                 ["**Nein!** Der Streithelfer tritt dem Verfahren zur **Unterstützung** eines von einer Partei begehrten Anspruchs bei (R. 313.2 VerfO); er wird zwar als Partei behandelt (R. 315.4) und ist an die Entscheidung gebunden (R. 316.3), hat aber keine von der unterstützten Partei unabhängige Stellung. Er darf sich nicht in Widerspruch zu deren Prozesshandlungen setzen; sein Widerspruch gegen die Rücknahme der Berufung ist unzulässig. Haben Partei und Streithelfer Berufung eingelegt, ist es ein **einheitliches Rechtsmittel**, das nach der Rücknahme durch die Partei infolge des Vergleichs nach R. 360 VerfO gegenstandslos wird (Strabag/Swarco).",
                  "Scheidet die unterstützte Partei aus, wird die Streithilfe unzulässig; kostenrechtlich wird der Streithelfer wie die Hauptpartei behandelt. Wer ein eigenes Interesse verfolgen will, muss selbst klagen – etwa auf Feststellung der Nichtverletzung vor der Zentralkammer (Art. 32 Abs. 1 lit. b, Art. 33 Abs. 4 EPGÜ). Die Rücknahme der Berufung selbst folgt R. 265 VerfO entsprechend; das Gericht entscheidet über die Kosten."],
                 merke="Der Streithelfer unterstützt, er führt nicht: Nimmt seine Partei zurück, ist auch seine Berufung erledigt.",
                 level=2, concepts=["upc_streithilfe", "upc_ruecknahme"],
                 norms=["R. 313 VerfO", "R. 315 VerfO", "R. 316 VerfO", "R. 360 VerfO"],
                 cases=["upc_coa_strabag_swarco_streithilfe"], step="step:upc_schema_berufung.3"),
            fall("u03c-3", "Der übergangene Kernvortrag",
                 "Die H-Inc. verteidigt sich vor einer Lokalkammer gegen den Vorwurf der Verletzung mit einem ausführlich begründeten Auslegungsargument: Das Merkmal „Filterelement“ verlange nach der Beschreibung zwingend eine mechanische Rückhaltefunktion, die ihrem Produkt fehle. Das Urteil gibt der Klage statt; in den Gründen wird das Argument in einem Satz als „Einwand zur Auslegung“ erwähnt, ohne auf die Beschreibungsstellen einzugehen, und der Anspruch wird nach dem Wortlaut ausgelegt. Die H-Inc. rügt in der Berufung die Verletzung ihres rechtlichen Gehörs.",
                 "Liegt eine Verletzung des rechtlichen Gehörs vor?", True,
                 ["**Ja!** Nach Art. 76 Abs. 2 EPGÜ dürfen Sachentscheidungen nur auf Gründe, Tatsachen und Beweismittel gestützt werden, zu denen die Parteien Stellung nehmen konnten. Das rechtliche Gehör verpflichtet das Gericht darüber hinaus, den Vortrag der Parteien **zur Kenntnis zu nehmen**, seinen wesentlichen Kern zu behandeln und auf zentrale Fragen in den Gründen einzugehen. Eine Verletzung ist zu vermuten, wenn die Gründe nur den Schluss zulassen, dass der Vortrag völlig übergangen wurde, oder wenn sie allenfalls den **Wortlaut, nicht den Sinn** des Vortrags erfassen (Siemens/Hologic). Genau das ist hier der Fall: Das Auslegungsargument war der Kern der Verteidigung, und die Gründe setzen sich mit den Beschreibungsstellen nicht auseinander.",
                  "Nicht jedes Argument muss ausdrücklich behandelt werden, die Kernargumente aber schon. Die zweite Seite des Art. 76 EPGÜ ist die **Dispositionsmaxime** (Abs. 1): Das Gericht entscheidet nur über die Anträge der Parteien und spricht nicht mehr zu als beantragt. Der Kläger bestimmt den Streitgegenstand und kann einzelne Handlungen oder Staaten ausklammern („carve-out“), um parallele Zuständigkeiten in der Übergangszeit zu vermeiden; das beschränkt aber nicht den Beklagten in seinem Angriff auf den Rechtsbestand (LK Paris, DexCom/Abbott). Berufungskläger müssen darlegen, dass der Verfahrensfehler zu einer unrichtigen Entscheidung geführt haben kann (Sinocare/Abbott)."],
                 merke="Gehör heißt Kenntnisnahme und Auseinandersetzung mit dem Kern; Gründe, die nur den Wortlaut des Vortrags wiedergeben, tragen die Vermutung der Gehörsverletzung.",
                 level=2, concepts=["upc_rechtliches_gehoer"],
                 norms=["Art. 76 EPGÜ", "R. 264 VerfO"],
                 cases=["upc_coa_siemens_hologic_gehoer", "upc_cfi_dexcom_abbott_dispositionsmaxime", "upc_coa_sinocare_abbott_zustaendigkeit"], step="step:upc_schema_berufung.5"),
        ]),
    ],
)
